def hopcroft(n, sigma, trans, part, blocks):
    """Coarsest stable refinement of `part` (fallback for wide automata)."""
    members = [[] for _ in range(blocks)]
    for q in range(n):
        members[part[q]].append(q)
    block_of = part[:]

    preds = []
    for c in range(sigma):
        counts = [0] * n
        for q in range(n):
            counts[trans[q][c]] += 1
        start = [0] * (n + 1)
        total = 0
        for i in range(n):
            start[i] = total
            total += counts[i]
        start[n] = total
        flat = [0] * n
        cursor = start[:]
        for q in range(n):
            target = trans[q][c]
            flat[cursor[target]] = q
            cursor[target] += 1
        preds.append((start, flat))

    waiting = deque(range(blocks))
    queued = [True] * blocks
    counter = [0] * blocks
    marked = bytearray(n)

    while waiting:
        current = waiting.popleft()
        queued[current] = False
        source = members[current]
        for c in range(sigma):
            start, flat = preds[c]
            touched = []
            hits = []
            for state in source:
                for pos in range(start[state], start[state + 1]):
                    q = flat[pos]
                    ident = block_of[q]
                    if counter[ident] == 0:
                        touched.append(ident)
                    counter[ident] += 1
                    marked[q] = 1
                    hits.append(q)
            for ident in touched:
                inside = counter[ident]
                counter[ident] = 0
                group = members[ident]
                if inside == len(group):
                    continue
                kept = []
                moved = []
                for q in group:
                    if marked[q]:
                        kept.append(q)
                    else:
                        moved.append(q)
                if len(moved) <= len(kept):
                    members[ident] = kept
                    fresh = moved
                else:
                    members[ident] = moved
                    fresh = kept
                new_id = len(members)
                members.append(fresh)
                counter.append(0)
                queued.append(False)
                for q in fresh:
                    block_of[q] = new_id
                if queued[ident]:
                    queued[new_id] = True
                    waiting.append(new_id)
                elif len(fresh) <= len(members[ident]):
                    queued[new_id] = True
                    waiting.append(new_id)
                else:
                    queued[ident] = True
                    waiting.append(ident)
            for q in hits:
                marked[q] = 0
    dense = {}
    final = [0] * n
    for q in range(n):
        ident = block_of[q]
        mapped = dense.get(ident)
        if mapped is None:
            mapped = len(dense)
            dense[ident] = mapped
        final[q] = mapped
    return final, len(dense)


def minimize(n, sigma, trans, accept):
    """Canonical minimal DFA: (accept, next rows, distance)."""
    if n == 1:
        part = [0]
        blocks = 1
    else:
        part, blocks = seed_partition(n, sigma, trans, accept)
        if blocks < n:
            part, blocks, done = moore(n, trans, part, blocks)
            if not done:
                part, blocks = hopcroft(n, sigma, trans, part, blocks)

    reps = [-1] * blocks
    for q in range(n):
        ident = part[q]
        if reps[ident] < 0:
            reps[ident] = q
    qtrans = [None] * blocks
    qaccept = [0] * blocks
    for ident in range(blocks):
        rep = reps[ident]
        qtrans[ident] = [part[x] for x in trans[rep]]
        qaccept[ident] = accept[rep]
    start = part[0]

    order = [start]
    numbering = {start: 0}
    head = 0
    while head < len(order):
        ident = order[head]
        head += 1
        for target in qtrans[ident]:
            if target not in numbering:
                numbering[target] = len(order)
                order.append(target)

    count = len(order)
    nxt = [[0] * sigma for _ in range(count)]
    acc = [False] * count
    for new_id, ident in enumerate(order):
        row = qtrans[ident]
        out = nxt[new_id]
        for c in range(sigma):
            out[c] = numbering[row[c]]
        acc[new_id] = bool(qaccept[ident])

    reverse = [[] for _ in range(count)]
    for q in range(count):
        for target in nxt[q]:
            if target != q:
                reverse[target].append(q)
    dist = [None] * count
    queue = deque()
    for q in range(count):
        if acc[q]:
            dist[q] = 0
            queue.append(q)
    while queue:
        state = queue.popleft()
        step = dist[state] + 1
        for prev in reverse[state]:
            if dist[prev] is None:
                dist[prev] = step
                queue.append(prev)
    return acc, nxt, dist


